// ── Validación y sanitización de datos entrantes ──
const body = $input.first().json.body;
const files = $input.first().binary;

// Validar campos requeridos
const required = ['student_id', 'full_name', 'email', 'absence_date', 'absence_reason'];
const missing = required.filter(f => !body[f]);

if (missing.length > 0) {
  throw new Error(`Campos requeridos faltantes: ${missing.join(', ')}`);
}

// Sanitizar inputs
const sanitize = str => str ? str.toString().trim().replace(/<[^>]*>/g, '').substring(0, 500) : '';

// Generar request code temporal (será reemplazado por PostgreSQL)
const timestamp = Date.now();
const tempCode = `JUS-${new Date().getFullYear()}-${String(timestamp).slice(-5)}`;

// Detectar tipo de archivo
const fileKey = Object.keys(files || {})[0];
const fileData = files?.[fileKey];
const fileType = fileData?.mimeType || 'unknown';

// Validar tipo de archivo permitido
const allowedTypes = ['image/jpeg', 'image/jpg', 'image/png', 'application/pdf'];
if (fileData && !allowedTypes.includes(fileType)) {
  throw new Error(`Tipo de archivo no permitido: ${fileType}. Solo PDF, JPG, PNG.`);
}

// Validar tamaño (5MB máx)
if (fileData && fileData.fileSize > 5 * 1024 * 1024) {
  throw new Error('El archivo supera el límite de 5 MB.');
}

return [{
  json: {
    temp_request_code: tempCode,
    student_id:        sanitize(body.student_id),
    full_name:         sanitize(body.full_name),
    email:             sanitize(body.email),
    program:           sanitize(body.program || ''),
    telegram_id:       sanitize(body.telegram_id || ''),
    absence_date:      body.absence_date,
    absence_reason:    body.absence_reason,
    description:       sanitize(body.description || ''),
    has_file:          !!fileData,
    file_type:         fileType,
    file_key:          fileKey || null,
    received_at:       new Date().toISOString()
  },
  binary: files || {}
}];

// ── Marcar solicitud como duplicada y enviar alerta ──
return [{
  json: {
    ...$json,
    status: 'rejected',
    classification: 'invalida',
    confidence_score: 0,
    decision_reason: 'Documento duplicado: ya fue presentado en una solicitud anterior.',
    fraud_flags: JSON.stringify([{ type: 'duplicate_document', severity: 'high' }])
  }
}];

// ── Manejar solicitud sin archivo adjunto ──
const data = $json;
return [{ json: {
  ...data,
  ocr_raw_text: '',
  ocr_cleaned_text: data.description || 'No se adjuntó documento de soporte.',
  ocr_quality: 'none'
}}];

