// 1. Parsear la respuesta de la IA de forma segura
let aiResult;
const rawInput = $json.message?.content || $json.text || "";

// Limpiamos el texto por si Gemini devuelve markdown como ```json ... ```
const cleanJson = rawInput.replace(/```json\n?|\n?```/g, "").trim();

try {
  aiResult = JSON.parse(cleanJson);
} catch (e) {
  // Si falla el parseo, devolvemos un valor seguro por defecto
  aiResult = {
    clasificacion: 'pendiente',
    confianza: 'baja',
    decision_reason: 'Error al interpretar la respuesta de la IA.',
    fecha_detectada: null
  };
}

// 2. Definir umbrales (evitamos process.env)
const HIGH = 80;
const MID = 40;

// 3. Normalizar puntaje de confianza (si es string, convertir a número)
const score = parseInt(aiResult.confianza === 'alta' ? 90 : (aiResult.confianza === 'media' ? 50 : 10)) || 0;

// 4. Lógica de decisión
let finalStatus, finalClassification;

if (score >= HIGH) {
  finalStatus = 'approved';
  finalClassification = 'valida';
} else if (score <= MID) {
  finalStatus = 'rejected';
  finalClassification = 'invalida';
} else {
  finalStatus = 'manual_review';
  finalClassification = 'dudosa';
}

// 5. Retornar los datos enriquecidos
return [{ 
  json: {
    ...$input.all()[0].json, // Mantenemos los datos anteriores
    final_status: finalStatus,
    final_classification: finalClassification,
    confidence_score: score,
    ai_analysis: aiResult,
    decision_reason: aiResult.decision_reason || "Sin motivo",
    document_type: aiResult.document_type || "desconocido"
  }
}];

// ── Construir mensaje Telegram según resultado ──
const statusEmoji = {
  'approved':      '✅',
  'rejected':      '❌',
  'manual_review': '🔍',
  'error':         ''
};

const statusLabel = {
  'approved':      'APROBADA',
  'rejected':      'RECHAZADA',
  'manual_review': 'EN REVISIÓN MANUAL',
  'error':         'ERROR DE PROCESAMIENTO'
};

const emoji = statusEmoji[$json.final_status] || '📋';
const label = statusLabel[$json.final_status] || $json.final_status.toUpperCase();
const score = Math.round($json.confidence_score || 0);

const message = `${emoji} *Solicitud ${label}*

` +
  `📋 Código: \`${$json.request_code}\`
` +
  `👤 Estudiante: ${$json.full_name}
` +
  `📅 Fecha inasistencia: ${$json.absence_date}
` +
  `📌 Motivo: ${$json.absence_reason}
` +
  `🎯 Score de confianza: ${score}%

` +
  `*Análisis:*
${$json.decision_reason || 'Sin detalles disponibles.'}

` +
  ` _Procesado automáticamente por Sistema IA_`;

// Chat ID del estudiante (si tiene Telegram)
const chatId = $json.telegram_id || null;

return [{ json: {
  ...$json,
  telegram_message: message,
  telegram_chat_id: chatId
}}];

