// 1. Acceder a los datos de forma segura
const inputData = $input.all();
const items = [];

for (const item of inputData) {
  // CAMBIO AQUÍ: buscamos 'file' en lugar de 'data'
  const fileHash = item.binary?.file ? (item.binary.file.fileName + "_" + item.binary.file.fileSize) : "no_hash";

  const previousNode = $items("Crear Solicitud en DB");
  const requestCode = previousNode[0].json.request_code;
  const requestId = previousNode[0].json.id;

  items.push({
    json: {
      ...item.json,
      request_id: requestId,
      request_code: requestCode,
      file_hash: fileHash
    },
    binary: item.binary // Esto es correcto, mantiene todo el objeto binary
  });
}

return items;

