// ── Procesar respuesta OCR (Extracción de datos del input actual) ──
let ocrResponse;
try {
  const rawData = ($json.body) ? $json.body : $json;
  ocrResponse = (typeof rawData === 'string') ? JSON.parse(rawData) : rawData;
} catch (e) {
  throw new Error('Error al parsear el JSON de la API: ' + e.message);
}

// En lugar de buscar el nodo Webhook, tomamos los datos que ya vienen en el flujo actual
// n8n automáticamente trae los datos anteriores si no los has limpiado.
// Usamos el objeto $input que contiene todo lo que llegó al nodo.
const inputData = $input.all()[0].json;

const parsedResult = ocrResponse.ParsedResults[0];
const rawText = parsedResult.ParsedText || '';
const cleanText = rawText.replace(/[^\x20-\x7E\xC0-\xFF\n]/g, ' ').trim();

// Construimos el JSON final combinando todo
return [{ 
  json: {
    ...inputData, // Esto toma TODO lo que entró al nodo (id, nombre, etc.)
    ocr_raw_text: rawText,
    ocr_cleaned_text: cleanText,
    ocr_exit_code: parsedResult.FileParseExitCode || 0
  }
}];

// Recuperar el archivo que el nodo anterior borró
// Lo buscamos en la entrada original del flujo (el Webhook)
const originalData = $('Webhook Recepción').first();

return items.map(item => ({
  json: item.json,
  binary: originalData.binary // Inyectamos el archivo original aquí
}));
